export const WIDGET_STYLES = ":root {\n  --ms-fg: #16181d;\n  --ms-muted: #61656e;\n  --ms-line: #e3e5ea;\n  --ms-bg: transparent;\n  --ms-accent: #2f6df6;\n  --ms-error: #b42318;\n  --ms-track: #eceef2;\n}\n@media (prefers-color-scheme: dark) {\n  :root {\n    --ms-fg: #e8eaee;\n    --ms-muted: #9aa0ab;\n    --ms-line: #2c3038;\n    --ms-accent: #7aa2ff;\n    --ms-error: #f9847a;\n    --ms-track: #23272f;\n  }\n}\n* {\n  box-sizing: border-box;\n}\nbody {\n  margin: 0;\n  color: var(--ms-fg);\n  background: var(--ms-bg);\n  font:\n    14px/1.5 ui-sans-serif,\n    system-ui,\n    -apple-system,\n    \"Segoe UI\",\n    sans-serif;\n}\n.ms-widget {\n  padding: 12px 14px;\n}\n.ms-title {\n  margin: 0 0 10px;\n  font-size: 15px;\n  font-weight: 600;\n}\n.ms-empty,\n.ms-count {\n  margin: 8px 0 0;\n  color: var(--ms-muted);\n  font-size: 12px;\n}\n.ms-error {\n  margin: 0;\n  color: var(--ms-error);\n}\n.ms-link {\n  color: var(--ms-accent);\n  font-weight: 500;\n  text-decoration: none;\n}\n.ms-link:hover {\n  text-decoration: underline;\n}\n\n.ms-results {\n  margin: 0;\n  padding-left: 20px;\n  display: grid;\n  gap: 14px;\n}\n.ms-url {\n  color: var(--ms-muted);\n  font-size: 12px;\n  word-break: break-all;\n}\n.ms-snippet {\n  margin: 4px 0 0;\n}\n\n.ms-table {\n  width: 100%;\n  border-collapse: collapse;\n  display: block;\n  overflow-x: auto;\n}\n.ms-table th,\n.ms-table td {\n  padding: 6px 10px;\n  border-bottom: 1px solid var(--ms-line);\n  text-align: left;\n  vertical-align: top;\n  max-width: 320px;\n  overflow-wrap: anywhere;\n}\n.ms-table th {\n  font-weight: 600;\n  white-space: nowrap;\n}\n\n.ms-fields {\n  margin: 0;\n  display: grid;\n  grid-template-columns: auto 1fr;\n  gap: 4px 14px;\n}\n.ms-fields dt {\n  color: var(--ms-muted);\n}\n.ms-fields dd {\n  margin: 0;\n  overflow-wrap: anywhere;\n}\n\n.ms-stats {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 10px;\n}\n.ms-stat {\n  display: grid;\n  gap: 2px;\n  padding: 8px 12px;\n  border: 1px solid var(--ms-line);\n  border-radius: 8px;\n  min-width: 120px;\n}\n.ms-stat-label {\n  color: var(--ms-muted);\n  font-size: 12px;\n}\n.ms-stat-value {\n  font-size: 16px;\n  font-weight: 600;\n}\n.ms-meter {\n  margin-top: 12px;\n  height: 6px;\n  border-radius: 999px;\n  background: var(--ms-track);\n  overflow: hidden;\n}\n.ms-meter-fill {\n  height: 100%;\n  background: var(--ms-accent);\n}\n";

